package main

import (
	"fmt"
	"sort"
)

const mod = 998244353
const N = 5000

var factor = [N + 1][]int{}
var primes = []int64{}

func comb(m int, n int) int64 {
	res := int64(1)
	fnm := make([]int, len(primes))
	copy(fnm, factor[n])
	for i, x := range factor[m] {
		fnm[i] += x
	}
	for w := 1; w <= m; w++ {
		r := int64(1)
		for i, p := range primes {
			for pw := fnm[i] - factor[w][i] - factor[n-w][i] -
				factor[m-w][i]; pw > 0; pw >>= 1 {
				if pw&1 == 1 {
					r = r * p % mod
				}
				p = p * p % mod
			}
		}
		res += r
	}
	return res % mod
}

func main() {
	abc := []int{0, 0, 0}
	fmt.Scan(&abc[0], &abc[1], &abc[2])
	sort.Ints(abc)
	sieve := [N + 1]bool{true, true}
	for p := range sieve {
		if !sieve[p] {
			primes = append(primes, int64(p))
			for q := p * p; q <= N; q += p {
				sieve[q] = true
			}
		}
	}
	for j := range factor {
		factor[j] = make([]int, len(primes))
	}
	for i, p := range primes {
		for pp := p; pp <= N; pp *= p {
			for j := pp; j <= N; j += pp {
				factor[j][i]++
			}
		}
	}
	a := factor[0]
	for _, b := range factor {
		for i, x := range a {
			b[i] += x
		}
		a = b
	}
	fmt.Println(comb(abc[0], abc[1]) * comb(abc[0], abc[2]) % mod * comb(abc[1], abc[2]) % mod)
}
